import { Mesh, PlaneGeometry, MeshBasicNodeMaterial, DoubleSide } from 'three/webgpu';
import { texture, uv, vec3, mix, float, hash } from 'three/tsl';

export default function createNode(config, ctx) {
  const mapTexture = ctx.textureLoader(config.imageUrl);

  const region = config.atlasRegion || { x: 0, y: 0, w: 512, h: 320 };
  const aspect = region.w / region.h;

  const geometry = new PlaneGeometry(aspect, 1, 1, 1);

  // Remap UVs into the atlas region (flipY-safe for image-space top-left origin)
  const img = mapTexture && mapTexture.image;
  if (img && img.width && img.height) {
    const tw = img.width;
    const th = img.height;
    const u0 = region.x / tw;
    const u1 = (region.x + region.w) / tw;
    const v1 = 1.0 - (region.y / th);
    const v0 = 1.0 - ((region.y + region.h) / th);
    const uvAttr = geometry.attributes.uv;
    const arr = uvAttr.array;
    for (let i = 0; i < uvAttr.count; i++) {
      const u = arr[i * 2];
      const v = arr[i * 2 + 1];
      arr[i * 2] = u0 + u * (u1 - u0);
      arr[i * 2 + 1] = v0 + v * (v1 - v0);
    }
    uvAttr.needsUpdate = true;
  }

  // TSL color graph: brushed-metal sample * engineered gradient + static grain
  const texColor = texture(mapTexture, uv());

  // Engineered vertical gradient — paper-bright top, ink-shaded bottom (subtle)
  const shade = mix(float(0.88), float(1.02), uv().y);

  // Static grain (no time animation — "static composition")
  const grain = hash(uv().mul(2048.0)).sub(float(0.5)).mul(0.035);

  const colorNode = texColor.rgb.mul(shade).add(vec3(grain));

  const material = new MeshBasicNodeMaterial();
  material.colorNode = colorNode;
  material.side = DoubleSide;
  material.transparent = false;
  material.toneMapped = false;

  const mesh = new Mesh(geometry, material);

  const pos = config.position || [3.2, -0.3, 0];
  const rot = config.rotation || [0, 0, 0];
  const scl = config.scale || [1, 1, 1];
  mesh.position.set(pos[0], pos[1], pos[2]);
  mesh.rotation.set(rot[0], rot[1], rot[2]);
  mesh.scale.set(scl[0], scl[1], scl[2]);

  mesh.userData.atlasRegion = region;
  mesh.userData.handlers = {};

  let disposed = false;
  mesh.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;
    geometry.dispose();
    material.dispose();
    // NOTE: mapTexture is owned by ctx.textureLoader cache — do not dispose here.
  };

  return mesh;
}
